  "admin.baseUrlHint": { "zh-CN": "留空时使用环境变量里的内置地址；填了就对所有用户生效。", "zh-TW": "留空時使用環境變數裡的內定位址；填了就對所有使用者生效。", en: "Leave blank to use the built-in endpoint from env vars; a value here applies to all users.", fr: "Laisser vide pour l'endpoint intégré des variables d'environnement ; une valeur ici s'applique à tous." },
