  "settings.disclaimer4": { "zh-CN": "建议使用额度受限的子密钥，并定期轮换。", "zh-TW": "建議使用額度受限的子金鑰，並定期輪換。", en: "Use a quota-limited sub-key and rotate it regularly.", fr: "Utilisez une sous-clé à quota limité et changez-la régulièrement." },
