  "settings.r2BoundTitle": { "zh-CN": "✓ 已通过 Worker 绑定直连 R2", "zh-TW": "✓ 已透過 Worker 綁定直連 R2", en: "✓ Connected to R2 through the Worker binding", fr: "✓ Connecté à R2 via la liaison Worker" },
  "settings.r2BoundA": { "zh-CN": "桶是本站自己的，Worker 通过 binding 直接读写，", "zh-TW": "桶是本站自己的，Worker 透過 binding 直接讀寫，", en: "The bucket belongs to this site and the Worker reads/writes it directly — ", fr: "Le bucket appartient à ce site et le Worker y accède directement — " },
