  "settings.publicDomainC": { "zh-CN": "填写 → 直接用你的域名访问，建议开 CDN 加速。", "zh-TW": "填寫 → 直接用你的網域存取，建議開 CDN 加速。", en: "Fill it in → files load straight from your domain, a CDN is recommended.", fr: "Remplissez-le → les fichiers sont servis par votre domaine, un CDN est conseillé." },
  "settings.siteManagedTitle": { "zh-CN": "站点已配置 R2，可直接使用", "zh-TW": "站點已設定 R2，可直接使用", en: "R2 is configured on this site — ready to use", fr: "R2 est configuré sur ce site — prêt à l'emploi" },
  "settings.siteManagedA": { "zh-CN": "管理员已在服务端配好存储桶。点下面的按钮即可上传，", "zh-TW": "管理員已在伺服器端設定好儲存桶。點下面的按鈕即可上傳，", en: "The admin already configured a bucket server-side. Press the button below to upload — ", fr: "L'administrateur a déjà configuré un bucket côté serveur. Cliquez sur le bouton ci-dessous pour téléverser — " },
