  "settings.enableStorageDesc": { "zh-CN": "开启后图片 / 视频上传到你的存储桶，只回传链接", "zh-TW": "開啟後圖片 / 影片上傳到你的儲存桶，只回傳連結", en: "Images / videos go to your bucket and only a link is sent", fr: "Les images / vidéos vont dans votre bucket et seul un lien est envoyé" },
  "settings.presetLabel": { "zh-CN": "服务商预设", "zh-TW": "服務商預設", en: "Provider presets", fr: "Préréglages de fournisseur" },
  "settings.presetHint": { "zh-CN": "点击预设会填入 Endpoint 与 Region 示例，把尖括号部分换成你自己的。", "zh-TW": "點擊預設會填入 Endpoint 與 Region 範例，把尖括號部分換成你自己的。", en: "Presets fill in Endpoint and Region examples — replace the angle-bracket parts with your own.", fr: "Les préréglages remplissent Endpoint et Region — remplacez les parties entre chevrons par les vôtres." },
  "settings.siteManagedNotice": { "zh-CN": "当前使用站点托管的 R2，密钥保存在服务器，浏览器不持有。如需改用你自己的存储，关掉上面的「使用站点配置」再填写。", "zh-TW": "目前使用站點代管的 R2，金鑰保存在伺服器，瀏覽器不持有。如需改用你自己的儲存，關掉上面的「使用站點設定」再填寫。", en: "Using the site-managed R2: keys stay on the server, not in your browser. To use your own storage, turn off “Use site config” above.", fr: "R2 géré par le site : les clés restent sur le serveur, pas dans votre navigateur. Pour utiliser votre stockage, désactivez « Utiliser la config du site » ci-dessus." },
  "settings.endpointPlaceholder": { "zh-CN": "https://<accountid>.r2.cloudflarestorage.com", "zh-TW": "https://<accountid>.r2.cloudflarestorage.com", en: "https://<accountid>.r2.cloudflarestorage.com", fr: "https://<accountid>.r2.cloudflarestorage.com" },
