  "settings.publicDomainHint2": { "zh-CN": "填了自定义域名就用它拼外链；留空则用 Endpoint/Bucket/Key。", "zh-TW": "填了自訂網域就用它拼外鏈；留空則用 Endpoint/Bucket/Key。", en: "A custom domain is used to build links; otherwise Endpoint/Bucket/Key.", fr: "Un domaine personnalisé sert à construire les liens ; sinon Endpoint/Bucket/Key." },
  "settings.twoSettings": { "zh-CN": "两个必要设置", "zh-TW": "兩個必要設定", en: "Two required settings", fr: "Deux réglages requis" },
  "settings.req1A": { "zh-CN": "1. 存储桶要允许", "zh-TW": "1. 儲存桶要允許", en: "1. The bucket must allow ", fr: "1. Le bucket doit autoriser " },
